def create_samples(apps, schema_editor):
    """One dummy (2 units) per ring offered for trial or already sent in a kit; kits now point to dummies."""
    Ring = apps.get_model("catalog", "Ring")
    SampleRing = apps.get_model("trialkit", "SampleRing")
    TrialKitOrder = apps.get_model("trialkit", "TrialKitOrder")
    used = set(TrialKitOrder.rings.through.objects.values_list("ring_id", flat=True))
    samples = {}
    for ring in Ring.objects.all():
        if ring.available_for_trial or ring.pk in used:
            samples[ring.pk] = SampleRing.objects.create(
                reference=f"FAC-{ring.pk:03d}", ring=ring, quantity=2, is_active=ring.available_for_trial
            )
    for kit in TrialKitOrder.objects.all():
        kit.samples.set([samples[ring.pk] for ring in kit.rings.all()])


